CREATE TABLE public.badges (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, abbreviation text NOT NULL, description_base text, description_gold text, description_hof text, description_diamond text, description_actolytrene text, affected_stat text, effect_type text DEFAULT 'reroll'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, status content_status DEFAULT 'active'::content_status NOT NULL, publish_at timestamp with time zone, starts_at timestamp with time zone, ends_at timestamp with time zone, disabled_at timestamp with time zone, archived_at timestamp with time zone, category text, supported_tiers text[], metadata jsonb, PRIMARY KEY (id));
CREATE TABLE public.evo_card_version_badges (id uuid DEFAULT gen_random_uuid() NOT NULL, evo_card_version_id uuid NOT NULL, badge_id uuid NOT NULL, tier text DEFAULT 'base'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.evo_card_version_traits (id uuid DEFAULT gen_random_uuid() NOT NULL, evo_card_version_id uuid NOT NULL, trait_id uuid NOT NULL, tier text DEFAULT 'base'::text NOT NULL, target_stat text, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.evo_card_versions (id uuid DEFAULT gen_random_uuid() NOT NULL, evo_path_id uuid NOT NULL, base_player_card_id uuid NOT NULL, version_order integer NOT NULL, gem_tier_id uuid, gem_name text, rating numeric, stat_3pt integer DEFAULT 0 NOT NULL, stat_mid integer DEFAULT 0 NOT NULL, stat_fin integer DEFAULT 0 NOT NULL, stat_dnk integer DEFAULT 0 NOT NULL, stat_ast integer DEFAULT 0 NOT NULL, stat_stl integer DEFAULT 0 NOT NULL, stat_reb integer DEFAULT 0 NOT NULL, stat_blk integer DEFAULT 0 NOT NULL, stat_int integer DEFAULT 0 NOT NULL, status content_status DEFAULT 'draft'::content_status NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.evo_objectives (id uuid DEFAULT gen_random_uuid() NOT NULL, evo_path_id uuid NOT NULL, group_key text DEFAULT 'default'::text NOT NULL, objective_type text NOT NULL, stat_key text, scope text DEFAULT 'cumulative'::text NOT NULL, target numeric NOT NULL, description text, sort_order integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.evo_paths (id uuid DEFAULT gen_random_uuid() NOT NULL, player_card_id uuid NOT NULL, from_tier_id uuid, to_tier_id uuid, step_order integer DEFAULT 1 NOT NULL, challenge_description text DEFAULT ''::text NOT NULL, challenge_type text DEFAULT 'points_scored'::text NOT NULL, challenge_target integer DEFAULT 100 NOT NULL, stat_boosts jsonb DEFAULT '{}'::jsonb NOT NULL, new_badges jsonb DEFAULT '[]'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, challenge_stat text, evolves_to_card_id uuid, compound_challenges jsonb DEFAULT '[]'::jsonb NOT NULL, new_traits jsonb DEFAULT '[]'::jsonb NOT NULL, status content_status DEFAULT 'active'::content_status NOT NULL, publish_at timestamp with time zone, starts_at timestamp with time zone, ends_at timestamp with time zone, disabled_at timestamp with time zone, archived_at timestamp with time zone, is_repeatable boolean DEFAULT false NOT NULL, objective_mode text DEFAULT 'all'::text NOT NULL, objectives jsonb DEFAULT '[]'::jsonb NOT NULL, final_rating numeric, final_stats jsonb, badge_upgrades jsonb DEFAULT '[]'::jsonb NOT NULL, trait_upgrades jsonb DEFAULT '[]'::jsonb NOT NULL, card_color_primary text, card_color_secondary text, card_glow_color text, card_animation text, avatar_url text, market_value integer, sort_order integer DEFAULT 0 NOT NULL, tier_progression_override boolean DEFAULT false NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.gem_tiers (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, stars integer DEFAULT 0 NOT NULL, roll_modifier numeric DEFAULT 0 NOT NULL, doubles_modifier numeric, color text NOT NULL, sort_order integer DEFAULT 0 NOT NULL, gem_value integer DEFAULT 0 NOT NULL, status content_status DEFAULT 'active'::content_status NOT NULL, publish_at timestamp with time zone, starts_at timestamp with time zone, ends_at timestamp with time zone, disabled_at timestamp with time zone, archived_at timestamp with time zone, abbreviation text, glow_color text, rating_min numeric, rating_max numeric, market_rules jsonb, max_badges integer, max_traits integer, PRIMARY KEY (id));
CREATE TABLE public.player_cards (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, gem_tier_id uuid, gem_name text, team_id uuid, position1 text, position2 text, rating numeric DEFAULT 0 NOT NULL, stat_3pt integer DEFAULT 0 NOT NULL, stat_mid integer DEFAULT 0 NOT NULL, stat_fin integer DEFAULT 0 NOT NULL, stat_dnk integer DEFAULT 0 NOT NULL, stat_ast integer DEFAULT 0 NOT NULL, stat_stl integer DEFAULT 0 NOT NULL, stat_reb integer DEFAULT 0 NOT NULL, stat_blk integer DEFAULT 0 NOT NULL, stat_int integer DEFAULT 0 NOT NULL, is_collection_reward boolean DEFAULT false NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, card_color_primary text, card_color_secondary text, card_glow_color text, card_animation text, run_rating integer, run_stat_3pt integer, run_stat_mid integer, run_stat_fin integer, run_stat_dnk integer, run_stat_stl integer, run_stat_blk integer, run_stat_ast integer, run_stat_reb integer, run_stat_int integer, market_value integer DEFAULT 500 NOT NULL, social_handle text, avatar_url text, collection_id uuid, sub_collection_id uuid, card_key text DEFAULT ''::text NOT NULL, card_variant text, evo_stage integer DEFAULT 0 NOT NULL, base_card_id uuid, status content_status DEFAULT 'active'::content_status NOT NULL, publish_at timestamp with time zone, starts_at timestamp with time zone, ends_at timestamp with time zone, disabled_at timestamp with time zone, archived_at timestamp with time zone, release_bundle_id uuid, PRIMARY KEY (id));
CREATE TABLE public.signature_traits (id uuid DEFAULT gen_random_uuid() NOT NULL, name text NOT NULL, abbreviation text NOT NULL, description_base text, description_gold text, description_hof text, description_diamond text, description_actolytrene text, condition_type text, created_at timestamp with time zone DEFAULT now() NOT NULL, status content_status DEFAULT 'active'::content_status NOT NULL, publish_at timestamp with time zone, starts_at timestamp with time zone, ends_at timestamp with time zone, disabled_at timestamp with time zone, archived_at timestamp with time zone, category text, supported_tiers text[], requires_target_stat boolean DEFAULT false NOT NULL, supported_target_stats text[], metadata jsonb, PRIMARY KEY (id));